const out=[];
for (const [i,item] of $input.all().entries()) {
 const input=$('05 | Contexto para OpenAI').all()[i]?.json ?? $('05 | Contexto para OpenAI').first().json;
 let j;try { j=JSON.parse(item.json?.choices?.[0]?.message?.content ?? '{}'); }
 catch {j={};}
 if(!j || typeof j!=='object' || Array.isArray(j)) j={};
 const areas=['trabalhista','empresarial','civil','cartorario_reurb','previdenciario','tributario'];
 const actions=['perguntar','oferecer_horarios','confirmar_horario','humano','encerrar'];
 const etapas=['recepcao','entendimento','coleta_dados','agendamento','encerramento'];
 const clean=(v,n)=>typeof v==='string'?v.slice(0,n):'';
 const resultado={
  nome_cliente:clean(j.nome_cliente,120),area:areas.includes(j.area)?j.area:null,
  tipo_caso:j.tipo_caso==='sem_registro'?'sem_registro':'geral',
  etapa:etapas.includes(j.etapa)?j.etapa:'entendimento',
  dados_coletados:j.dados_coletados && typeof j.dados_coletados==='object' && !Array.isArray(j.dados_coletados)?j.dados_coletados:{},
  resumo_fatos:clean(j.resumo_fatos,3500),
  prioridade:['alta','media','baixa'].includes(j.prioridade)?j.prioridade:'media',
  motivo_prioridade:clean(j.motivo_prioridade,250),
  acao:actions.includes(j.acao)?j.acao:'humano',
  slot_escolhido:[1,2,3].includes(Number(j.slot_escolhido))?Number(j.slot_escolhido):null,
  mensagem_ao_cliente:clean(j.mensagem_ao_cliente,650)
 };
 // Não permita confirmar uma data que não tenha sido OFERECIDA pelo CRM.
 const slots=$('04c | Contexto atualizado').all()[i]?.json?.estado?.slots ?? [];
 if(resultado.acao==='confirmar_horario' &&
    (!Array.isArray(slots) || !slots.some(s=>Number(s.opcao)===resultado.slot_escolhido))) {
    resultado.acao='perguntar';resultado.mensagem_ao_cliente='Qual das opções oferecidas você prefere: 1, 2 ou 3?';
 }
 out.push({json:{telefone:input.telefone,provider_id:input.provider_id,resultado},pairedItem:i});
}
return out;

const out=[];
for(const i of $input.all()) {
 const j=i.json;
 if(Array.isArray(j)) { for(const v of j) { if(v?.id && v?.telefone) out.push({json:v}); } }
 else if(j?.id && j?.telefone) { out.push({json:j}); }
}
return out;

const out=[];
for (const [i,it] of $input.all().entries()){
 const j=it.json;
 const teste=String($env.MODO_TESTE??'true').toLowerCase()!=='false';
 const aprovado=String($env.COMPLIANCE_APROVADO??'false').toLowerCase()==='true';
 const permitidos=String($env.TELEFONES_TESTE??'').split(',').map(x=>x.replace(/\D/g,'')).filter(Boolean);
 const template=String($env.META_FOLLOWUP_TEMPLATE??'');
 const br=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',hour:'2-digit',hour12:false,weekday:'short'}).formatToParts(new Date());
 const weekday=br.find(x=>x.type==='weekday')?.value;
 const hour=Number(br.find(x=>x.type==='hour')?.value);
 const horario=/^(Mon|Tue|Wed|Thu|Fri)$/.test(weekday||'') && hour>=9 && hour<18;
 const telefone=String(j.telefone||'').replace(/\D/g,'');
 let permitir=/^55[1-9][0-9]9[0-9]{8}$/.test(telefone)
   && (teste?permitidos.includes(telefone):aprovado);
 if(j.tipo==='followup') permitir=permitir && Boolean(template) && horario;
 const msg=teste?'[TESTE] '+String(j.texto||''):String(j.texto||'');
 let corpo;
 if(j.tipo==='followup') {
   corpo={messaging_product:'whatsapp',to:telefone,type:'template',
    template:{name:template,language:{code:'pt_BR'}}};
 } else {
   corpo={messaging_product:'whatsapp',recipient_type:'individual',to:telefone,
    type:'text',text:{preview_url:false,body:msg.slice(0,4000)}};
 }
 out.push({json:{...j,permitir,meta_body:corpo,bloqueio:permitir?'':'teste/compliance/template/horario'},pairedItem:i});
}
return out;

return $input.all().map((it,i)=>{
  const id=String(it.json?.messages?.[0]?.id||'');
  if(!id) throw new Error('Meta não retornou ID: possível envio ambíguo, NÃO reenviar automaticamente');
  const prev=$('15 | Portão de compliance e modo teste').item.json;
  return {json:{id:prev.id,provider_id:id},pairedItem:i};
});
